import React from 'react';
import { Audio } from '@remotion/media';
import { Sequence, staticFile, useVideoConfig } from 'remotion';
import { sec } from './time';

/**
 * Shared SFX registry: only files that exist in public/sfx/ (generated by
 * videos/phone-listening/make_sfx.py). Unknown names are skipped, never fatal.
 */
export const SFX_FILES = {
  pop: { file: 'sfx/pop.wav', dur: 0.36 },
  'pop-soft': { file: 'sfx/pop-soft.wav', dur: 0.27 },
  stamp: { file: 'sfx/stamp.wav', dur: 0.72 },
  whoosh: { file: 'sfx/whoosh.wav', dur: 0.85 },
  'whoosh-short': { file: 'sfx/whoosh-short.wav', dur: 0.3 },
  tick: { file: 'sfx/tick.wav', dur: 0.04 },
  'tick-roll': { file: 'sfx/tick-roll.wav', dur: 1.4 },
  scan: { file: 'sfx/scan.wav', dur: 1.05 },
  shutter: { file: 'sfx/shutter.wav', dur: 0.42 },
  type: { file: 'sfx/type.wav', dur: 0.75 },
  lock: { file: 'sfx/lock.wav', dur: 0.38 },
  unlock: { file: 'sfx/unlock.wav', dur: 1.35 },
  hit: { file: 'sfx/hit.wav', dur: 1.6 },
  glow: { file: 'sfx/glow.wav', dur: 1.7 },
  hum: { file: 'sfx/hum.wav', dur: 1.6 },
  morph: { file: 'sfx/morph.wav', dur: 0.75 },
  draw: { file: 'sfx/draw.wav', dur: 0.8 },
  steps: { file: 'sfx/steps.wav', dur: 1.55 },
  zoom: { file: 'sfx/zoom.wav', dur: 0.45 },
  strike: { file: 'sfx/strike.wav', dur: 0.25 },
  ding: { file: 'sfx/ding.wav', dur: 1.5 },
  buzz: { file: 'sfx/buzz.wav', dur: 0.62 },
} as const;

export type SfxName = keyof typeof SFX_FILES;
export type SfxCue = { at: number; name: string; volume?: number };

const known = (n: string): n is SfxName => n in SFX_FILES;

/** Places each cue (absolute seconds) as a short <Audio> in its own Sequence. */
export const SfxTrack: React.FC<{ cues: SfxCue[] }> = ({ cues }) => {
  const { fps } = useVideoConfig();
  return (
    <>
      {cues.map((c, i) => {
        if (!known(c.name)) return null;
        const s = SFX_FILES[c.name];
        return (
          <Sequence key={i} name={`sfx ${c.name}`} from={sec(Math.max(0, c.at), fps)} durationInFrames={sec(s.dur, fps) + 2} layout="none">
            <Audio src={staticFile(s.file)} volume={c.volume ?? 0.5} />
          </Sequence>
        );
      })}
    </>
  );
};

export const unknownSfx = (cues: SfxCue[]) => cues.filter((c) => !known(c.name)).map((c) => c.name);
